PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "django_migrations" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app" varchar(255) NOT NULL, "name" varchar(255) NOT NULL, "applied" datetime NOT NULL);
CREATE TABLE IF NOT EXISTS "auth_group_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "auth_user_groups" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "auth_user_user_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "django_admin_log" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "object_id" text NULL, "object_repr" varchar(200) NOT NULL, "action_flag" smallint unsigned NOT NULL CHECK ("action_flag" >= 0), "change_message" text NOT NULL, "content_type_id" integer NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "action_time" datetime NOT NULL);
CREATE TABLE IF NOT EXISTS "django_content_type" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app_label" varchar(100) NOT NULL, "model" varchar(100) NOT NULL);
CREATE TABLE IF NOT EXISTS "auth_permission" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "content_type_id" integer NOT NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "codename" varchar(100) NOT NULL, "name" varchar(255) NOT NULL);
CREATE TABLE IF NOT EXISTS "auth_group" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(150) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS "auth_user" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "password" varchar(128) NOT NULL, "last_login" datetime NULL, "is_superuser" bool NOT NULL, "username" varchar(150) NOT NULL UNIQUE, "last_name" varchar(150) NOT NULL, "email" varchar(254) NOT NULL, "is_staff" bool NOT NULL, "is_active" bool NOT NULL, "date_joined" datetime NOT NULL, "first_name" varchar(150) NOT NULL);
CREATE TABLE IF NOT EXISTS "django_session" ("session_key" varchar(40) NOT NULL PRIMARY KEY, "session_data" text NOT NULL, "expire_date" datetime NOT NULL);
CREATE TABLE IF NOT EXISTS "tailors_order" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "order_date" date NOT NULL, "delivery_date" date NOT NULL, "customer_id" bigint NOT NULL REFERENCES "tailors_addcustomer" ("id") DEFERRABLE INITIALLY DEFERRED, "tailor_id" bigint NULL REFERENCES "tailors_addtailor" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "tailors_workstatus" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "status" varchar(20) NOT NULL, "customer_id" bigint NOT NULL REFERENCES "tailors_addcustomer" ("id") DEFERRABLE INITIALLY DEFERRED, "tailor_id" bigint NOT NULL REFERENCES "tailors_addtailor" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "tailors_addtailor" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "tailor" varchar(100) NULL, "username" varchar(100) NULL UNIQUE, "password" varchar(10) NULL, "mobile_number" varchar(15) NULL UNIQUE);
CREATE TABLE IF NOT EXISTS "tailors_addcustomer" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(100) NOT NULL, "phone_number" varchar(15) NOT NULL, "length" varchar(15) NOT NULL, "shoulder" varchar(15) NOT NULL, "loose" varchar(15) NOT NULL, "neck" varchar(15) NOT NULL, "regal" varchar(15) NOT NULL, "cuf" varchar(15) NOT NULL, "sleeve" varchar(15) NOT NULL, "tailor_id" bigint NULL REFERENCES "tailors_addtailor" ("id") DEFERRABLE INITIALLY DEFERRED, "bill_number" varchar(50) NOT NULL UNIQUE, "bottom1" varchar(50) NULL, "bottom2" varchar(50) NULL, "button_type" varchar(15) NULL, "delivery_date" date NULL, "order_date" date NULL, "sleeve_type" varchar(15) NOT NULL, "cuftype" varchar(10) NOT NULL, "pocket_size" varchar(15) NULL);
CREATE TABLE IF NOT EXISTS "dashboard_order" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "details" text NOT NULL, "order_date" date NOT NULL, "delivery_date" date NOT NULL, "customer_id" bigint NOT NULL REFERENCES "dashboard_customer" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "authtoken_token" ("key" varchar(40) NOT NULL PRIMARY KEY, "created" datetime NOT NULL, "user_id" integer NOT NULL UNIQUE REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "dashboard_addtailors_groups" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "addtailors_id" integer NOT NULL REFERENCES "dashboard_addtailors" ("id") DEFERRABLE INITIALLY DEFERRED, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "dashboard_addtailors_user_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "addtailors_id" integer NOT NULL REFERENCES "dashboard_addtailors" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "dashboard_addtailors" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "tailor" varchar(100) NULL, "username" varchar(100) NULL UNIQUE, "password" varchar(10) NULL, "date_joined" datetime NOT NULL, "email" varchar(254) NOT NULL, "first_name" varchar(150) NOT NULL, "is_active" bool NOT NULL, "is_staff" bool NOT NULL, "is_superuser" bool NOT NULL, "last_login" datetime NULL, "last_name" varchar(150) NOT NULL, "assigned_works" integer NOT NULL, "completed_works" integer NOT NULL, "pending_works" integer NOT NULL, "upcoming_works" integer NOT NULL, "mobile_number" varchar(15) NULL UNIQUE);
CREATE TABLE IF NOT EXISTS "dashboard_item" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "item_name" varchar(100) NULL, "item_quantity" integer unsigned NULL CHECK ("item_quantity" >= 0), "item_price" real NULL, "total_price" real NULL, "order_id_id" bigint NULL REFERENCES "dashboard_add_order" ("id") DEFERRABLE INITIALLY DEFERRED, "customer_id" bigint NULL REFERENCES "dashboard_customer" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "dashboard_reception_login" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "password" varchar(20) NULL, "user_name" varchar(20) NULL);
CREATE TABLE IF NOT EXISTS "dashboard_cloth" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(100) NOT NULL, "length" decimal NOT NULL, "stock_length" decimal NOT NULL);
CREATE TABLE IF NOT EXISTS "dashboard_admin_login" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "password" varchar(20) NULL, "username" varchar(20) NULL);
CREATE TABLE IF NOT EXISTS "dashboard_add_order" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "length" varchar(15) NOT NULL, "shoulder" varchar(15) NOT NULL, "cloth" varchar(20) NULL, "regal" varchar(15) NOT NULL, "loose" varchar(15) NOT NULL, "pocket" varchar(15) NOT NULL, "bottom1" varchar(50) NOT NULL, "button_type" varchar(15) NOT NULL, "order_date" date NOT NULL, "delivery_date" date NOT NULL, "description" varchar(100000) NULL, "bill_number" varchar(15) NULL, "status" varchar(20) NOT NULL, "tailor_id" integer NULL REFERENCES "dashboard_addtailors" ("id") DEFERRABLE INITIALLY DEFERRED, "customer_id_id" bigint NULL REFERENCES "dashboard_customer" ("id") DEFERRABLE INITIALLY DEFERRED, "seat" varchar(15) NULL, "sleeve_cuff" varchar(15) NULL, "sleeve_sada" varchar(15) NULL, "sleeve_bottom" varchar(15) NULL, "advance_payment" varchar(15) NULL, "balance_payment" varchar(15) NULL, "total_payment" varchar(15) NULL, "pending_or_delivered" varchar(20) NOT NULL, "collar_measurements" varchar(15) NULL, "cuff_measurements" varchar(15) NULL, "collar_type_image_url" varchar(255) NULL, "cuff_type_image_url" varchar(255) NULL, "collar_type" varchar(15) NULL, "cuff_type" varchar(15) NULL, "center_sleeve" varchar(15) NULL, "model_details" varchar(100000) NULL, "ordered_length" decimal NULL, "pocket_image_url" varchar(255) NULL, "pocket_type" varchar(15) NULL, "clothdetails_id" bigint NULL REFERENCES "dashboard_cloth" ("id") DEFERRABLE INITIALLY DEFERRED, "is_printed" bool NOT NULL, "cloth_name" varchar(100) NULL);
CREATE TABLE IF NOT EXISTS "dashboard_customer" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(100) NOT NULL, "mobile" varchar(15) NOT NULL, "length" varchar(15) NOT NULL, "shoulder" varchar(15) NOT NULL, "regal" varchar(15) NOT NULL, "loose" varchar(15) NOT NULL, "pocket" varchar(15) NOT NULL, "bottom1" varchar(50) NOT NULL, "button_type" varchar(15) NOT NULL, "order_date" date NOT NULL, "delivery_date" date NOT NULL, "tailor_id" integer NULL REFERENCES "dashboard_addtailors" ("id") DEFERRABLE INITIALLY DEFERRED, "description" varchar(100000) NULL, "bill_number" varchar(15) NULL, "status" varchar(20) NOT NULL, "cloth" varchar(20) NULL, "seat" varchar(15) NULL, "sleeve_cuff" varchar(15) NULL, "sleeve_sada" varchar(15) NULL, "sleeve_bottom" varchar(15) NULL, "collar_measurements" varchar(15) NULL, "cuff_measurements" varchar(15) NULL, "collar_type_image_url" varchar(255) NULL, "cuff_type_image_url" varchar(255) NULL, "collar_type" varchar(15) NULL, "cuff_type" varchar(15) NULL, "center_sleeve" varchar(15) NULL, "model_details" varchar(100000) NULL, "ordered_length" decimal NULL, "pocket_image_url" varchar(255) NULL, "pocket_type" varchar(15) NULL, "clothdetails_id" bigint NULL REFERENCES "dashboard_cloth" ("id") DEFERRABLE INITIALLY DEFERRED, "cloth_name" varchar(100) NULL);
DELETE FROM sqlite_sequence;
